namespace Folha {
interface Remote {
 List<Dictionary<string,object>> Files();
 string Upload(string name,string file,Dictionary<string,object> properties);
 void Download(string id,string target,long limit);
}
sealed class Drive:Remote {
 readonly string token;
 public Drive(string token){this.token=token;}
 public static HttpWebRequest Request(string url,string method,string token){var r=(HttpWebRequest)WebRequest.Create(url);r.Method=method;r.Timeout=120000;r.ReadWriteTimeout=120000;r.AllowAutoRedirect=false;r.UserAgent="Folha/0.6.1";if(token!=null)r.Headers["Authorization"]="Bearer "+token;return r;}
 public static HttpWebResponse Response(HttpWebRequest r){try{return (HttpWebResponse)r.GetResponse();}catch(WebException e){var h=e.Response as HttpWebResponse;var status=h==null?0:(int)h.StatusCode;if(h!=null)h.Dispose();if(status==401)throw new Exception("Sua sessão expirou. Conecte a conta Google novamente.");if(status==403)throw new Exception("O Google recusou o acesso. Confira a permissão do Folha no Drive ou a cota da conta.");if(status==429||status>=500)throw new Exception("O Drive está ocupado. A sincronização tentará novamente; seus arquivos estão salvos no aparelho.");throw new Exception("Sem conexão com o Google Drive. Seus arquivos locais estão preservados.");}}
 static string Read(HttpWebResponse r){using(r)using(var s=new StreamReader(r.GetResponseStream(),Encoding.UTF8))return s.ReadToEnd();}
 public List<Dictionary<string,object>> Files(){var all=new List<Dictionary<string,object>>();string next="";do{var url="https://www.googleapis.com/drive/v3/files?spaces=appDataFolder&pageSize=1000&fields=nextPageToken,files(id,name,appProperties,size)&q="+Uri.EscapeDataString("trashed = false and appProperties has { key='folha' and value='1' }")+"&pageToken="+Uri.EscapeDataString(next);var j=J.Parse(Read(Response(Request(url,"GET",token))));all.AddRange(J.List(j["files"]).Select(J.Obj));next=J.S(j,"nextPageToken");if(all.Count>200000)throw new Exception("Biblioteca do Drive grande demais para esta versão.");}while(next!="");return all;}
 public string Upload(string name,string file,Dictionary<string,object> properties){var meta=J.Encode(new{name=name,parents=new[]{"appDataFolder"},appProperties=properties});var r=Request("https://www.googleapis.com/upload/drive/v3/files?uploadType=resumable&fields=id","POST",token);r.ContentType="application/json; charset=UTF-8";r.Headers["X-Upload-Content-Type"]="application/octet-stream";r.Headers["X-Upload-Content-Length"]=new FileInfo(file).Length.ToString();var b=Encoding.UTF8.GetBytes(meta);r.ContentLength=b.Length;using(var s=r.GetRequestStream())s.Write(b,0,b.Length);string location;using(var reply=Response(r))location=reply.Headers["Location"];var uri=new Uri(location);if(uri.Scheme!="https"||uri.Host!="www.googleapis.com")throw new Exception("Destino de envio inválido.");var put=Request(location,"PUT",token);put.ContentType="application/octet-stream";put.ContentLength=new FileInfo(file).Length;put.AllowWriteStreamBuffering=false;using(var src=File.OpenRead(file))using(var dst=put.GetRequestStream())src.CopyTo(dst,65536);return J.S(J.Parse(Read(Response(put))),"id");}
 public void Download(string id,string target,long limit){if(!System.Text.RegularExpressions.Regex.IsMatch(id,@"^[a-zA-Z0-9_-]+$"))throw new Exception("Arquivo remoto inválido.");var r=Request("https://www.googleapis.com/drive/v3/files/"+id+"?alt=media","GET",token);using(var response=Response(r)){if(response.ContentLength>limit)throw new Exception("Arquivo do Drive excede o limite.");using(var src=response.GetResponseStream())using(var dst=File.Create(target))Store.CopyBounded(src,dst,limit);}}
}
sealed class SyncEngine {
 readonly Store store;readonly Remote remote;readonly Func<string> opened;readonly string stateDir;Dictionary<string,object> state;List<Dictionary<string,object>> files;int deferred,conflicts;
 public SyncEngine(Store store,Remote remote,string account,Func<string> opened){this.store=store;this.remote=remote;this.opened=opened;stateDir=Path.Combine(store.StateRoot,J.Hash(Encoding.UTF8.GetBytes(account)));Directory.CreateDirectory(stateDir);var f=Path.Combine(stateDir,"state.json");state=File.Exists(f)?J.Parse(File.ReadAllText(f)):new Dictionary<string,object>();}
 Dictionary<string,object> Base(string id){return state.ContainsKey(id)?J.Obj(state[id]):new Dictionary<string,object>();}
 void SaveBase(string id,string rev,Dictionary<string,object> doc){state[id]=new{rev=rev,hash=J.Fingerprint(doc)};J.Atomic(Path.Combine(stateDir,"state.json"),J.Encode(state));state=J.Parse(J.Encode(state));}
 static Dictionary<string,object> Props(Dictionary<string,object> f){return f.ContainsKey("appProperties")?J.Obj(f["appProperties"]):new Dictionary<string,object>();}
 static string Prop(Dictionary<string,object> f,string key){return J.S(Props(f),key);}
 static Dictionary<string,object> P(string kind){return new Dictionary<string,object>{{"folha","1"},{"kind",kind}};}
 public string Run(){files=remote.Files();object[] local;lock(store.Gate)local=store.Library(true);foreach(var item in local){var id=J.S(J.Obj(item),"id");Dictionary<string,object> doc;lock(store.Gate)doc=store.Read(id);if(doc.ContainsKey("pdfPending")&&Convert.ToBoolean(doc["pdfPending"]))continue;if(J.Fingerprint(doc)!=J.S(Base(id),"hash"))Push(doc,J.S(Base(id),"rev"));}
 var groups=files.Where(f=>Prop(f,"kind")=="rev"&&J.ValidId(Prop(f,"doc"))&&J.ValidId(Prop(f,"rev"))).GroupBy(f=>Prop(f,"doc")).ToList();foreach(var group in groups){var unique=group.GroupBy(f=>Prop(f,"rev")).Select(g=>g.First()).ToList();var heads=Heads(unique);if(heads.Count==0)continue;var winner=heads.OrderBy(f=>Prop(f,"time"),StringComparer.Ordinal).ThenBy(f=>Prop(f,"rev"),StringComparer.Ordinal).Last();foreach(var loser in heads.Where(f=>f!=winner)){var copyId=ConflictId(group.Key,Prop(loser,"rev"));bool exists;lock(store.Gate)exists=Directory.Exists(store.Dir(copyId));if(exists||files.Any(f=>Prop(f,"doc")==copyId))continue;var manifest=Manifest(loser);var copy=J.Parse(J.S(manifest,"document"));copy["originId"]=group.Key;copy["id"]=copyId;copy["name"]=J.S(copy,"name")+" (conflito "+Prop(loser,"rev").Substring(0,8)+")";Install(copy,manifest,null);Push(copy,"");conflicts++;}
 var rid=Prop(winner,"rev");if(J.S(Base(group.Key),"rev")==rid)continue;Dictionary<string,object> before=null;lock(store.Gate){if(File.Exists(Path.Combine(store.Dir(group.Key),"document.json")))before=store.Read(group.Key);}if(opened()==group.Key){deferred++;continue;}var hash=before==null?null:J.Fingerprint(before);if(before!=null&&hash!=J.S(Base(group.Key),"hash")){deferred++;continue;}var m=Manifest(winner);var d=J.Parse(J.S(m,"document"));if(Install(d,m,hash))SaveBase(group.Key,rid,d);else deferred++;}
 return deferred>0?"Sincronizado. Feche o caderno para receber alterações do outro aparelho.":conflicts>0?"Sincronizado. Edições simultâneas foram preservadas em cópias de conflito.":"Tudo sincronizado com o Drive.";}
 public static List<Dictionary<string,object>> Heads(List<Dictionary<string,object>> revs){var parents=new HashSet<string>(revs.Select(f=>Prop(f,"parent")).Where(x=>x!=""));return revs.Where(f=>!parents.Contains(Prop(f,"rev"))).ToList();}
 public static string ConflictId(string doc,string rev){var h=J.Hash(Encoding.UTF8.GetBytes("folha-conflict:"+doc+":"+rev));return h.Substring(0,8)+"-"+h.Substring(8,4)+"-"+h.Substring(12,4)+"-"+h.Substring(16,4)+"-"+h.Substring(20,12);}
 string Blob(string path){var hash=J.HashFile(path);var known=files.FirstOrDefault(f=>Prop(f,"kind")=="blob"&&Prop(f,"sha")==hash);if(known!=null)return J.S(known,"id");var p=P("blob");p["sha"]=hash;var id=remote.Upload(hash+".blob",path,p);files.Add(new Dictionary<string,object>{{"id",id},{"appProperties",p}});return id;}
 void Push(Dictionary<string,object> doc,string parent){var id=J.S(doc,"id");var assets=new Dictionary<string,object>();var names=new HashSet<string>();if(Convert.ToBoolean(doc["pdf"]))names.Add("source.pdf");foreach(var list in J.Obj(doc["pages"]).Values)foreach(var o in J.List(list)){var s=J.Obj(o);if(J.S(s,"kind")=="image")names.Add("assets/"+J.S(s,"asset"));}foreach(var n in names){var f=store.DataFile(id,n);assets[n]=new{file=Blob(f),sha=J.HashFile(f),size=new FileInfo(f).Length};}var rid=J.Id();var text=J.Encode(doc);var manifest=new{version=1,revision=rid,parent=parent,document=text,sha=J.Hash(Encoding.UTF8.GetBytes(text)),assets=assets};var temp=Path.Combine(stateDir,"upload.json");J.Atomic(temp,J.Encode(manifest));var p=P("rev");p["doc"]=id;p["rev"]=rid;p["parent"]=parent;p["time"]=J.Now().ToString("D16");var file=remote.Upload(rid+".json",temp,p);files.Add(new Dictionary<string,object>{{"id",file},{"appProperties",p}});SaveBase(id,rid,doc);}
 Dictionary<string,object> Manifest(Dictionary<string,object> f){var rid=Prop(f,"rev");var cache=Path.Combine(stateDir,rid+".json");if(!File.Exists(cache)){var temp=cache+".download";remote.Download(J.S(f,"id"),temp,32*1024*1024);File.Move(temp,cache);}var m=J.Parse(File.ReadAllText(cache));if(J.I(m,"version")!=1||J.S(m,"revision")!=rid||J.S(m,"sha")!=J.Hash(Encoding.UTF8.GetBytes(J.S(m,"document"))))throw new Exception("Versão remota inválida; a cópia local foi preservada.");var d=J.Parse(J.S(m,"document"));Store.Validate(d);if(J.S(d,"id")!=Prop(f,"doc"))throw new Exception("Caderno remoto inválido.");return m;}
 bool Install(Dictionary<string,object> d,Dictionary<string,object> manifest,string expectedHash){var id=J.S(d,"id");Store.Validate(d);var temp=Path.Combine(stateDir,"stage-"+J.Id());Directory.CreateDirectory(temp);try{var assets=J.Obj(manifest["assets"]);foreach(var pair in assets){var target=store.DataFile(id,pair.Key);var info=J.Obj(pair.Value);var sha=J.S(info,"sha");if(!System.Text.RegularExpressions.Regex.IsMatch(sha,"^[a-f0-9]{64}$"))throw new Exception("Assinatura de arquivo inválida.");if(File.Exists(target)&&J.HashFile(target)==sha)continue;var staged=Path.Combine(temp,pair.Key.Replace('/',Path.DirectorySeparatorChar));Directory.CreateDirectory(Path.GetDirectoryName(staged));remote.Download(J.S(info,"file"),staged,1024L*1024*1024);if(J.HashFile(staged)!=sha)throw new Exception("Arquivo incompleto no Drive. O original local foi preservado.");}if(Convert.ToBoolean(d["pdf"])&&!assets.ContainsKey("source.pdf"))throw new Exception("PDF ausente na versão do Drive.");foreach(var list in J.Obj(d["pages"]).Values)foreach(var obj in J.List(list)){var s=J.Obj(obj);if(J.S(s,"kind")=="image"&&!assets.ContainsKey("assets/"+J.S(s,"asset")))throw new Exception("Imagem ausente no Drive.");}
 lock(store.Gate){if(opened()==id)return false;var exists=File.Exists(Path.Combine(store.Dir(id),"document.json"));if(expectedHash==null&&exists)return false;if(expectedHash!=null&&(!exists||J.Fingerprint(store.Read(id))!=expectedHash))return false;Directory.CreateDirectory(store.Dir(id));foreach(var pair in assets){var staged=Path.Combine(temp,pair.Key.Replace('/',Path.DirectorySeparatorChar));if(File.Exists(staged)){var dest=store.DataFile(id,pair.Key);Directory.CreateDirectory(Path.GetDirectoryName(dest));File.Copy(staged,dest,true);}}store.Write(d);}return true;
 }finally{Directory.Delete(temp,true);}}
}
sealed class Cloud {
 readonly Store store;readonly string root;readonly Func<string> opened;readonly Action changed;readonly SemaphoreSlim busy=new SemaphoreSlim(1,1);readonly Timer timer;Dictionary<string,object> session;string access="",message="Seus arquivos estão salvos neste PC.";long expires,edited,lastSync;bool running;
 public Cloud(Store store,string root,Func<string> opened,Action changed){this.store=store;this.root=root;this.opened=opened;this.changed=changed;try{var f=Path.Combine(root,"account.bin");if(File.Exists(f))session=J.Parse(Encoding.UTF8.GetString(ProtectedData.Unprotect(File.ReadAllBytes(f),null,DataProtectionScope.CurrentUser)));}catch{message="Conecte novamente a conta Google. Seus cadernos estão preservados.";}timer=new Timer(_=>{if(session!=null&&J.Now()-edited>15000)Start();},null,30000,30000);}
 public object Status(){return new{connected=session!=null,email=session==null?"":J.S(session,"email"),busy=running,message=message,lastSync=lastSync};}
 public void Edited(){edited=J.Now();}
 public async Task<object> Connect(){if(!await busy.WaitAsync(0))throw new Exception("Aguarde a sincronização atual.");try{message="Conclua o login no navegador.";changed();var auth=await Task.Run(()=>OAuth.Authorize());access=J.S(auth,"access_token");expires=J.Now()+3300000;var r=Drive.Request("https://www.googleapis.com/oauth2/v3/userinfo","GET",access);Dictionary<string,object> user;using(var response=Drive.Response(r))using(var rd=new StreamReader(response.GetResponseStream()))user=J.Parse(await rd.ReadToEndAsync());if(!user.ContainsKey("sub"))throw new Exception("Não foi possível identificar a conta.");var ownerFile=Path.Combine(root,"library-owner");if(File.Exists(ownerFile)&&File.ReadAllText(ownerFile)!=J.S(user,"sub"))throw new Exception("Esta biblioteca pertence a outra conta. Reconecte a conta original para preservar a privacidade dos arquivos.");File.WriteAllText(ownerFile,J.S(user,"sub"));if(session!=null&&J.S(session,"sub")!=J.S(user,"sub"))throw new Exception("Desconecte a conta atual antes de trocar de conta.");session=new Dictionary<string,object>{{"sub",J.S(user,"sub")},{"email",J.S(user,"email")},{"refresh_token",J.S(auth,"refresh_token",session==null?"":J.S(session,"refresh_token"))}};var bytes=ProtectedData.Protect(Encoding.UTF8.GetBytes(J.Encode(session)),null,DataProtectionScope.CurrentUser);File.WriteAllBytes(Path.Combine(root,"account.bin"),bytes);message="Conta conectada. Iniciando sincronização…";changed();}finally{busy.Release();}Start();return Status();}
 public async Task Disconnect(){await busy.WaitAsync();try{session=null;access="";expires=0;var f=Path.Combine(root,"account.bin");if(File.Exists(f))File.Delete(f);message="Conta desconectada. Os cadernos continuam salvos no PC.";changed();}finally{busy.Release();}}
 public async void Start(){if(session==null||!await busy.WaitAsync(0))return;running=true;message="Sincronizando em segundo plano…";changed();try{var current=session;await Task.Run(()=>{if(J.Now()>=expires){var refresh=OAuth.Refresh(J.S(current,"refresh_token"));access=J.S(refresh,"access_token");expires=J.Now()+3300000;}message=new SyncEngine(store,new Drive(access),J.S(current,"sub"),opened).Run();lastSync=J.Now();});}catch(Exception e){message=e.Message;}finally{running=false;busy.Release();changed();}}
}
static class OAuth {
 const string Scopes="openid email https://www.googleapis.com/auth/drive.appdata";
 static Dictionary<string,object> Config(){var f=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"google-client.json");if(!File.Exists(f))throw new Exception("Login Google ainda não configurado nesta compilação.");var d=J.Parse(File.ReadAllText(f));return d.ContainsKey("installed")?J.Obj(d["installed"]):d;}
 static string Random(){var b=new byte[32];using(var rng=RandomNumberGenerator.Create())rng.GetBytes(b);return Convert.ToBase64String(b).TrimEnd('=').Replace('+','-').Replace('/','_');}
 static Dictionary<string,object> Token(Dictionary<string,string> p){var conf=Config();p["client_id"]=J.S(conf,"client_id");p["client_secret"]=J.S(conf,"client_secret");var form=string.Join("&",p.Select(x=>Uri.EscapeDataString(x.Key)+"="+Uri.EscapeDataString(x.Value)));var r=Drive.Request("https://oauth2.googleapis.com/token","POST",null);r.ContentType="application/x-www-form-urlencoded";var b=Encoding.UTF8.GetBytes(form);r.ContentLength=b.Length;using(var s=r.GetRequestStream())s.Write(b,0,b.Length);using(var response=Drive.Response(r))using(var rd=new StreamReader(response.GetResponseStream()))return J.Parse(rd.ReadToEnd());}
 public static Dictionary<string,object> Refresh(string token){if(token=="")throw new Exception("Conecte novamente sua conta Google.");return Token(new Dictionary<string,string>{{"grant_type","refresh_token"},{"refresh_token",token}});}
 public static Dictionary<string,object> Authorize(){var conf=Config();var listener=new TcpListener(IPAddress.Loopback,0);listener.Start();try{var port=((IPEndPoint)listener.LocalEndpoint).Port;var redirect="http://127.0.0.1:"+port+"/";var state=Random();var verifier=Random();string challenge;using(var h=SHA256.Create())challenge=Convert.ToBase64String(h.ComputeHash(Encoding.ASCII.GetBytes(verifier))).TrimEnd('=').Replace('+','-').Replace('/','_');var url="https://accounts.google.com/o/oauth2/v2/auth?client_id="+Uri.EscapeDataString(J.S(conf,"client_id"))+"&redirect_uri="+Uri.EscapeDataString(redirect)+"&response_type=code&scope="+Uri.EscapeDataString(Scopes)+"&state="+state+"&code_challenge="+challenge+"&code_challenge_method=S256&access_type=offline&prompt=consent";Process.Start(new ProcessStartInfo(url){UseShellExecute=true});var pending=listener.AcceptTcpClientAsync();if(!pending.Wait(240000))throw new Exception("O login não foi concluído. Tente novamente quando quiser.");using(var client=pending.Result){client.ReceiveTimeout=10000;var stream=client.GetStream();var reader=new StreamReader(stream,Encoding.ASCII,false,1024,true);var line=reader.ReadLine();if(line==null||line.Length>16384)throw new Exception("Resposta de login inválida.");var parts=line.Split(' ');if(parts.Length!=3||parts[0]!="GET")throw new Exception("Resposta inválida.");var uri=new Uri(redirect.TrimEnd('/')+parts[1]);var q=HttpUtility.ParseQueryString(uri.Query);if(q["state"]!=state||string.IsNullOrEmpty(q["code"]))throw new Exception("Login cancelado ou resposta de segurança inválida.");var html=Encoding.UTF8.GetBytes("<!doctype html><meta charset=utf-8><title>Folha</title><p>Conta conectada. Você já pode voltar ao Folha.</p>");var header=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: "+html.Length+"\r\nConnection: close\r\n\r\n");stream.Write(header,0,header.Length);stream.Write(html,0,html.Length);return Token(new Dictionary<string,string>{{"grant_type","authorization_code"},{"code",q["code"]},{"code_verifier",verifier},{"redirect_uri",redirect}});}}finally{listener.Stop();}}
}
}
